import { useState, useEffect } from 'react';
import InputLabel from '@mui/material/InputLabel';
import MenuItem from '@mui/material/MenuItem';
import FormHelperText from '@mui/material/FormHelperText';
import FormControl from '@mui/material/FormControl';
import Select from '@mui/material/Select';
import axios from 'axios';
import api from 'routes/api.json';
import { toast } from 'react-toastify';
// eslint-disable-next-line import/prefer-default-export
export default function SearchSmallRna(props) {
    // eslint-disable-next-line react-hooks/rules-of-hooks
    const [age, setAge] = useState('');
    const [Data, setData] = useState([]);

    const handleChange = (event) => {
        setAge(event.target.value);
    };

    const getLncRnaId = async () => {
        // eslint-disable-next-line prettier/prettier
        await axios
            .get('https://api.brassicalnc.com/lncRNA/small_rna_target/ids/')
            .then(async (res) => {
                console.log(res);
                await setData(res.data);
            })
            .catch(() =>
                toast.warn('server error. please try again later.', {
                    position: 'top-right',
                    autoClose: 5000,
                    hideProgressBar: false,
                    closeOnClick: true,
                    pauseOnHover: true,
                    draggable: true,
                    progress: undefined,
                    theme: 'light'
                })
            );
    };

    useEffect(() => {
        getLncRnaId();
    }, []);

    return (
        <div>
            <FormControl sx={{ m: 1, minWidth: 350 }}>
                <InputLabel id="demo-simple-select-helper-label">search in small Rna Target</InputLabel>
                <Select
                    labelId="demo-simple-select-helper-label"
                    id="demo-simple-select-helper"
                    value={age}
                    label="search in small Rna Target"
                    onChange={(event) => {
                        // eslint-disable-next-line react/prop-types
                        props.handleSelectSearch(event.target.value);
                        setAge(event.target.value);
                    }}
                >
                    <MenuItem value="">
                        <em>None</em>
                    </MenuItem>
                    {Data && Data.map((item) => <MenuItem value={item}>{item}</MenuItem>)}

                    {/* <MenuItem value={10}>Ten</MenuItem>
                    <MenuItem value={20}>Twenty</MenuItem>
                    <MenuItem value={30}>Thirty</MenuItem> */}
                </Select>
            </FormControl>
        </div>
    );
}
